import 'package:isar/isar.dart';

part 'isar_schemas.g.dart';
// ^ generated by: dart run build_runner build --delete-conflicting-outputs

/// Library index only - this never stores audio bytes, only paths + tags.
/// Mirrors the "Song Table" in the design doc.
@collection
class SongRecord {
  Id id = Isar.autoIncrement;

  @Index(unique: true, replace: true)
  late String path;

  late String filename;
  int durationMs = 0;
  String? artist;
  String? album;
  String? title;
  late DateTime modified;
  String? contentHash;
  String? artworkPath;
  int? metadataId; // FK -> MetadataRecord.id
  bool favorite = false;
  int playCount = 0;
  double? rating;
  bool hidden = false;
  int? bitrate;
  String? codec;
  int? sizeBytes;

  // Lyrics cache - independent of MetadataRecord matching, since LRCLIB
  // lookup only needs title/artist/album/duration (which every song has,
  // matched or not) and not every song gets a MetadataRecord.
  String? plainLyrics;
  String? syncedLyrics; // raw LRC-format text, parsed for display by LrcParser

  // Metadata-fetch retry tracking. Without this, a song that genuinely has
  // no online match AND no artwork available anywhere (embedded or online)
  // matches the "needs fetching" filter forever, since artworkPath stays
  // null no matter how many times it's retried - it gets reprocessed on
  // EVERY single run indefinitely, burning API calls/time on songs that
  // will never resolve while other genuinely-fixable songs wait behind it
  // in the queue.
  int fetchAttemptCount = 0;
  DateTime? lastFetchAttemptAt;
}

/// Mirrors the "Metadata Table".
@collection
class MetadataRecord {
  Id id = Isar.autoIncrement;

  late String officialTitle;
  late String officialArtist;
  String? album;
  String? genre;
  int? year;
  int? track;
  String? artworkUrl;
  double confidence = 0.0;
  late String source;
}

/// Mirrors the "Artist Table". Canonical name after Smart Artist Merge.
@collection
class ArtistRecord {
  Id id = Isar.autoIncrement;

  @Index(unique: true, replace: true)
  late String name;

  String? artworkPath;
  String? biography;
  int songCount = 0;
}

/// Mirrors the "Album Table". Canonical title after Smart Album Merge.
@collection
class AlbumRecord {
  Id id = Isar.autoIncrement;

  late int artistId;
  late String title;
  String? artworkPath;
  int? year;
}

/// Mirrors "History".
@collection
class HistoryRecord {
  Id id = Isar.autoIncrement;

  late int songId;
  late DateTime playedAt;
  int listenedMs = 0;
  bool skipped = false;
  bool completed = false;
}

/// Mirrors "Playlists" (junction table Playlist <-> Song <-> Position).
@collection
class PlaylistRecord {
  Id id = Isar.autoIncrement;

  late String name;
  List<int> songIdsOrdered = []; // song ids in playlist order
  bool isAuto = false;
  bool isAiGenerated = false;
}

/// Tracks metadata fetch runs so the user can review history.
@collection
class MetadataFetchHistoryRecord {
  Id id = Isar.autoIncrement;

  late DateTime ranAt;
  int totalProcessed = 0;
  int totalUpdated = 0;
  int totalNoMatch = 0;
  int totalErrors = 0;
  String? firstError;
  // New: how long the run took in seconds
  int durationSeconds = 0;
  // New: how many songs were matched via API vs local ID3 vs error
  int matchedByApi = 0;
  int matchedByLocal = 0;
  // New: titles of first 30 no-match songs for drill-down view
  List<String> noMatchSongTitles = [];
  // New: first error message per source
  String? apiErrorSample;
}

/// Tracks Library Health report runs.
@collection
class LibraryHealthHistoryRecord {
  Id id = Isar.autoIncrement;

  late DateTime ranAt;
  int totalSongs = 0;
  int missingTags = 0;
  int brokenArtwork = 0;
  int duplicates = 0;
}

/// Tracks recent search queries for the user.
@collection
class SearchHistoryRecord {
  Id id = Isar.autoIncrement;
  
  @Index(unique: true, replace: true)
  late String query;
  
  late DateTime searchedAt;
}